def base_string_uri(uri: str, host: str=None) ->str:
    if not isinstance(uri, str):
        raise ValueError('uri must be a string')

    if not uri or uri.isspace():
        raise ValueError('uri cannot be empty or whitespace')

    parsed = urlparse.urlparse(uri)

    if not parsed.scheme or not parsed.netloc:
        raise ValueError('uri must be a valid absolute URI')

    scheme = parsed.scheme.lower()

    if host:
        netloc = host.lower()
    else:
        netloc = parsed.hostname
        if netloc is None:
            raise ValueError('uri must have a valid hostname')
        netloc = netloc.lower()

    port = parsed.port

    if port is not None:
        if port <= 0 or port >= 65536:
            raise ValueError('port must be between 1 and 65535')
        if not ((scheme == 'http' and port == 80) or (scheme == 'https' and port == 443)):
            netloc = f"{netloc}:{port}"

    path = urlparse.quote(parsed.path, safe='/~')

    if not path:
        path = '/'

    return f"{scheme}://{netloc}{path}"


def collect_parameters(uri_query='', body=None, headers=None,
    exclude_oauth_signature=True, with_realm=False):
    params = []

    if uri_query:
        params.extend(urldecode(uri_query))

    if body:
        params.extend(urldecode(body))

    if headers:
        headers_lower = {k.lower(): v for k, v in headers.items()}

        if 'authorization' in headers_lower:
            auth_header = headers_lower['authorization']

            if auth_header.lower().startswith('oauth '):
                auth_header = auth_header[6:]

            auth_params = []
            for param in auth_header.split(','):
                param = param.strip()
                if '=' in param:
                    key, value = param.split('=', 1)
                    key = key.strip()
                    value = value.strip()

                    if value.startswith('"') and value.endswith('"'):
                        value = value[1:-1]

                    if exclude_oauth_signature and key.lower() == 'oauth_signature':
                        continue

                    if not with_realm and key.lower() == 'realm':
                        continue

                    auth_params.append((key, value))

            params.extend(auth_params)

    return params


def normalize_parameters(params) ->str:
    if not params:
        return ''

    key_values = []
    for k, v in params:
        if k.lower() == 'oauth_signature':
            continue
        key_values.append((utils.escape(str(k)), utils.escape(str(v))))

    key_values.sort()

    return '&'.join([f"{k}={v}" for k, v in key_values])
